import{_ as o,a0 as n,w as p,s as d,ao as l,I as r,x as a,a1 as t,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"使用 Fedora ARM 服务器来做 3-2-1 备份计划 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Fedora ARM 服务器来做 3-2-1 备份计划 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Fedora ARM 服务器来做 3-2-1 备份计划 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Fedora ARM 服务器来做 3-2-1 备份计划 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220415 3-2-1 Backup plan with Fedora ARM server","title":"使用 Fedora ARM 服务器来做 3-2-1 备份计划","tag":"202204","desc":""},"relativePath":"202204/20220415 3-2-1 Backup plan with Fedora ARM server.md","filePath":"[post].md"}'),h={name:"202204/20220415 3-2-1 Backup plan with Fedora ARM server.md"};function u(g,e,f,b,k,c){const i=n("Link");return p(),d("div",null,[e[43]||(e[43]=l('<h1 id="使用-fedora-arm-服务器来做-3-2-1-备份计划" tabindex="-1">使用 Fedora ARM 服务器来做 3-2-1 备份计划 <a class="header-anchor" href="#使用-fedora-arm-服务器来做-3-2-1-备份计划" aria-label="Permalink to “使用 Fedora ARM 服务器来做 3-2-1 备份计划”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/3-2-1_backup-816x345.jpg" alt=""></p><p>Fedora 服务器版操作系统可以运行在类似树莓派的单板计算机（SBC）上。这篇文章针对的用户是想要充分利用实体服务器系统，并使用类似 Cockpit 的内置工具进行数据备份和个人数据的恢复。这里描述了备份的 3 个阶段。</p><h3 id="必要的准备" tabindex="-1">必要的准备 <a class="header-anchor" href="#必要的准备" aria-label="Permalink to “必要的准备”">​</a></h3><p>想要使用本指南，你所需要的是一个运行着的 Fedora Linux 工作站和以下的项目：</p>',5)),r("ul",null,[r("li",null,[e[2]||(e[2]=a("你应该阅读、理解和实践 Fedora 文档中 ",-1)),t(i,{href:"https://docs.fedoraproject.org/en-US/fedora-server/server-installation-sbc/"},{default:s(()=>[...e[0]||(e[0]=[a("服务器安装",-1)])]),_:1}),e[3]||(e[3]=a(" 和 ",-1)),t(i,{href:"https://docs.fedoraproject.org/en-US/fedora-server/sysadmin-postinstall/"},{default:s(()=>[...e[1]||(e[1]=[a("管理",-1)])]),_:1}),e[4]||(e[4]=a(" 的要求",-1))]),r("li",null,[e[6]||(e[6]=a("一块用来测试 Fedora Linux 的 SBC（单板计算机）。在这里查看 ",-1)),t(i,{href:"https://docs.fedoraproject.org/en-US/quick-docs/raspberry-pi/"},{default:s(()=>[...e[5]||(e[5]=[a("硬件需求",-1)])]),_:1})]),r("li",null,[t(i,{href:"https://arm.fedoraproject.org/"},{default:s(()=>[...e[7]||(e[7]=[a("Fedora ARM",-1)])]),_:1}),e[9]||(e[9]=a()),t(i,{href:"https://arm.fedoraproject.org/"},{default:s(()=>[...e[8]||(e[8]=[a("服务器",-1)])]),_:1}),e[10]||(e[10]=a(" 原始镜像 & ARM 镜像安装器",-1))]),e[11]||(e[11]=r("li",null,"SD 存储卡（64 GB / Class 10）和 SSD 设备两选一",-1)),e[12]||(e[12]=r("li",null,"以太网 / DHCP 预留 IP 地址或者静态 IP 地址",-1)),e[13]||(e[13]=r("li",null,"提供了 ssh 密钥的 Linux 客户端工作站",-1)),e[14]||(e[14]=r("li",null,"选择云存储服务",-1)),e[15]||(e[15]=r("li",null,"有额外可用的 Linux 工作站",-1))]),e[44]||(e[44]=l('<p>对于这套环境，在写这篇文章的时候，由于成本和可用性的原因，我选择树莓派 3B+/4B+ （其中一个用来热切换）。当使用 Cockpit 远程连接树莓派服务器时，你可以将树莓派放到路由器附近以便设置。</p><h3 id="加强服务器的安全" tabindex="-1">加强服务器的安全 <a class="header-anchor" href="#加强服务器的安全" aria-label="Permalink to “加强服务器的安全”">​</a></h3><p>在 SBC 完成服务器的安装和管理后，用 firewalld 加强服务器的安全是一个好的做法。</p><p>连接存储设备到服务器之前，一旦服务器在线你必须设置好防火墙。firewalld 是基于区域的防火墙。在依照 Fedora 文档完成安装和管理指南之后，创建一个名为 <code>FedoraServer</code> 的预定义区域。</p><h4 id="firewalld-里的富规则" tabindex="-1">firewalld 里的富规则 <a class="header-anchor" href="#firewalld-里的富规则" aria-label="Permalink to “firewalld 里的富规则”">​</a></h4><p><ruby>富规则<rt>rich rule</rt></ruby>用来阻止或者允许一个特定的 IP 地址或者地址段。下面这条规则只从（客户端工作站）注册的 IP 地址接受 SSH 连接，并断开其它的连接。在 Cockpit 终端或者客户端工作站终端运行命令是通过 ssh 来连接到服务器的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-rich-rule=&#39;rule family=ipv4 source address=&lt;registered_ip_address&gt;/24 service name=ssh log prefix=&quot;SSH Logs&quot; level=&quot;notice&quot; accept&#39;</span></span></code></pre></div><h4 id="拒绝所有主机的-ping-请求" tabindex="-1">拒绝所有主机的 ping 请求 <a class="header-anchor" href="#拒绝所有主机的-ping-请求" aria-label="Permalink to “拒绝所有主机的 ping 请求”">​</a></h4><p>使用这个命令来设置 icmp 拒绝，并且不允许 ping 请求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-rich-rule=&#39;rule protocol value=icmp reject&#39;</span></span></code></pre></div><p>要进行其它防火墙控制，比如管理端口和区域，请查阅以下链接。请注意错配防火墙可能会使安全出现漏洞受到攻击。</p>',11)),r("blockquote",null,[r("p",null,[r("strong",null,[t(i,{href:"https://fedoramagazine.org/managing-network-interfaces-and-firewalld-in-cockpit/"},{default:s(()=>[...e[16]||(e[16]=[a("在 Cockpit 中管理防火墙",-1)])]),_:1})])])]),r("blockquote",null,[r("p",null,[r("strong",null,[t(i,{href:"https://www.redhat.com/sysadmin/firewalld-rules-and-scenarios"},{default:s(()=>[...e[17]||(e[17]=[a("firewalld 规则",-1)])]),_:1})])])]),e[45]||(e[45]=l('<h3 id="配置文件服务器的存储" tabindex="-1">配置文件服务器的存储 <a class="header-anchor" href="#配置文件服务器的存储" aria-label="Permalink to “配置文件服务器的存储”">​</a></h3><p>下一步是连接存储设备到 SBC，然后使用 Cockpit 对新插入的存储设备进行分区。使用 Cockpit 的图形化服务器管理界面，管理一个家庭实验室（可以是一个或者多个服务器）比之前更加简单。Fedora Linux 服务器标准提供了 Cockpit。</p><p>在这个阶段，一个通过 SBC 的 USB 插口接电的 SSD 设备无需额外电源供给就可以工作。</p><ul><li>将存储设备连接到 SBC 的 USB 接口</li><li>运行之后（按上面的“必要的准备”所设置的那样），然后在你的客户端工作站浏览器上访问 <strong>机器的 IP 地址:9090</strong></li><li>登录进 Cockpit 之后，点击 Cockpit 页面顶部的“<ruby>打开管理访问权限<rt>Turn on administrative access</rt></ruby>”</li><li>点击左边面板的 “<ruby>存储<rt>Storage</rt></ruby>” 按钮</li><li>选择下面显示的 “<ruby>驱动器<rt>Drives</rt></ruby>”，然后分区并格式化一个空白的存储设备 <img src="https://fedoramagazine.org/wp-content/uploads/2022/03/Screenshot-from-2022-03-29-22-05-00b-1024x576.png" alt="Cockpit Storage management"></li><li>在选定的存储设备这个界面上，创建一个新的分区表或者格式化并创建新的分区。当初始化磁盘的时候，在 “<ruby>Partitioning<rt>分区</rt></ruby>” 类型选项上，选择 “GPT 分区表”</li><li>选择一个文件系统类型，这里选择 “EXT4” 。这对于一个限制 I/O 能力（比如 USB 2.0 接口）和限制带宽（小于 200MB/s）的设备是适合的 <img src="https://fedoramagazine.org/wp-content/uploads/2022/03/Screenshot-from-2022-03-29-22-03-36a.png" alt="Create a partition in Cockpit"></li><li>要在设备上创建单个占据整个存储空间的分区，指定它的挂载点，比如 <code>/media</code> 然后点击 “<ruby>确定<rt>Ok</rt></ruby>” 。</li><li>点击 “<ruby>Create partition<rt>创建分区</rt></ruby>”，创建一个挂载点为 <code>/media</code> 的新分区。</li></ul><h3 id="创建备份和恢复备份" tabindex="-1">创建备份和恢复备份 <a class="header-anchor" href="#创建备份和恢复备份" aria-label="Permalink to “创建备份和恢复备份”">​</a></h3><p>备份很少是一刀切的。这里有一些选择比如数据备份在哪里，备份数据的步骤，验证一些自动化，并确定怎样来恢复备份了的数据。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Backups3-1-1024x525.jpg" alt="Backup workflow – version 1.0"></p><h4 id="备份-1-用-rsync-从客户端远程同步到文件服务器-树莓派" tabindex="-1">备份 1. 用 rsync 从客户端远程同步到文件服务器（树莓派） <a class="header-anchor" href="#备份-1-用-rsync-从客户端远程同步到文件服务器-树莓派" aria-label="Permalink to “备份 1. 用 rsync 从客户端远程同步到文件服务器（树莓派）”">​</a></h4><p>这个传输用到的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -azP ~/source syncuser@host1:/destination</span></span></code></pre></div><p>参数:</p><ul><li><code>-a</code>/<code>--archive</code>：归档</li><li><code>-z</code>/<code>--compress</code>：压缩</li><li><code>-P</code>/<code>--progress</code>：显示进度</li></ul><p>要使用更多的选项运行 <code>rsync</code>，可以设置以下的选项：</p><ul><li><code>--inplace</code>：直接替换来更新目标文档</li><li><code>--append</code>：追加数据到较短的文档中</li></ul><p>在将文档备份到存储空间之前，源端文档的文件重复消除和压缩是减少备份数据容量最有效的方式。</p><p>每天工作结束，我会手动运行这个。一旦我设置了云备份工作流，自动化脚本是一个优势。</p>',16)),r("p",null,[e[19]||(e[19]=a("关于 ",-1)),e[20]||(e[20]=r("code",null,"rsync",-1)),e[21]||(e[21]=a(" 的详细信息，请在 ",-1)),t(i,{href:"https://fedoramagazine.org/copying-large-files-with-rsync-and-some-misconceptions/"},{default:s(()=>[...e[18]||(e[18]=[a("这里",-1)])]),_:1}),e[22]||(e[22]=a(" 访问 Fedora 杂志的文章。",-1))]),e[46]||(e[46]=l('<h4 id="备份-2-使用-rysnc-从文件服务器远程同步到主要的云存储上" tabindex="-1">备份 2. 使用 rysnc 从文件服务器远程同步到主要的云存储上 <a class="header-anchor" href="#备份-2-使用-rysnc-从文件服务器远程同步到主要的云存储上" aria-label="Permalink to “备份 2. 使用 rysnc 从文件服务器远程同步到主要的云存储上”">​</a></h4><p>选择云存储是考虑的因素；</p><ul><li>成本：上传、存储空间和下载费用</li><li>支持 <code>rsync</code>、<code>sftp</code></li><li>数据冗余（RAID 10 或者运行中的数据中心冗余计划）</li><li>快照</li></ul>',3)),r("p",null,[e[24]||(e[24]=a("符合这些云存储标准之一的就是 Hetzner 托管的 Nextcloud– ",-1)),t(i,{href:"https://docs.hetzner.com/robot/storage-box/"},{default:s(()=>[...e[23]||(e[23]=[a("存储盒子",-1)])]),_:1}),e[25]||(e[25]=a("。你不会受到供应商限制，可以自由切换而没有退出惩罚。",-1))]),e[47]||(e[47]=l(`<h5 id="在文件服务器上生成-ssh-密钥并创建授权密钥文件" tabindex="-1">在文件服务器上生成 SSH 密钥并创建授权密钥文件 <a class="header-anchor" href="#在文件服务器上生成-ssh-密钥并创建授权密钥文件" aria-label="Permalink to “在文件服务器上生成 SSH 密钥并创建授权密钥文件”">​</a></h5><p>使用 <code>ssh-keygen</code> 命令为文件服务器和云存储生成一对新的 SSH 密钥对。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-keygen</span></span>
<span class="line"><span>Generating public/private rsa key pair.</span></span>
<span class="line"><span>Enter file in which to save the key . . .</span></span></code></pre></div><p>插入要求的 SSH 公钥到新的本地授权密钥文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat .ssh/id_rsa.pub &gt;&gt; storagebox_authorized_keys</span></span></code></pre></div><h5 id="传输密钥文件到云存储" tabindex="-1">传输密钥文件到云存储 <a class="header-anchor" href="#传输密钥文件到云存储" aria-label="Permalink to “传输密钥文件到云存储”">​</a></h5><p>下一步就是上传生成了的授权密钥文件到存储盒子。要做这些，先用 700 权限创建 <code>.ssh</code> 目录，然后用 SSH 公钥创建授权文件并赋予 600 权限。运行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo -e &quot;mkdir .ssh \\n chmod 700 .ssh \\n put storagebox_authorized_keys .ssh/authorized_keys \\n chmod 600 .ssh/authorized_keys&quot; | sftp &lt;username&gt;@&lt;username&gt;.your-storagebox.de</span></span></code></pre></div><h5 id="通过-ssh-使用-rsync" tabindex="-1">通过 ssh 使用 rsync <a class="header-anchor" href="#通过-ssh-使用-rsync" aria-label="Permalink to “通过 ssh 使用 rsync”">​</a></h5><p>使用 <code>rsync</code> 同步你的文件目录当前状态到存储盒子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync --progress -e &#39;ssh -p23&#39; --recursive &lt;local_directory&gt; &lt;username&gt;@&lt;username&gt;.your-storagebox.de:&lt;target_directory&gt;</span></span></code></pre></div><p>这个过程被叫做推送操作，因为它 “推送” 本地系统的一个目录到一个远程的系统中去。</p><h5 id="从云存储中恢复目录" tabindex="-1">从云存储中恢复目录 <a class="header-anchor" href="#从云存储中恢复目录" aria-label="Permalink to “从云存储中恢复目录”">​</a></h5><p>要从存储盒子恢复目录，转换到这个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync --progress -e &#39;ssh -p23&#39; --recursive &lt;username&gt;@&lt;username&gt;.your-storagebox.de:&lt;remote_directory&gt; &lt;local_directory&gt;</span></span></code></pre></div><h4 id="备份-3-客户端备份到第二个云储存" tabindex="-1">备份 3. 客户端备份到第二个云储存 <a class="header-anchor" href="#备份-3-客户端备份到第二个云储存" aria-label="Permalink to “备份 3. 客户端备份到第二个云储存”">​</a></h4>`,16)),r("p",null,[t(i,{href:"https://fedoramagazine.org/easy-backups-with-deja-dup/"},{default:s(()=>[...e[26]||(e[26]=[a("Deja Dup",-1)])]),_:1}),e[27]||(e[27]=a(" 是 Fedora 软件仓库中为 Fedora 工作站提供快速备份解决方案的工具。它拥有 GPG 加密、计划任务、文件包含（哪个目录要备份）等功能。",-1))]),e[48]||(e[48]=l('<p><img src="https://fedoramagazine.org/wp-content/uploads/2022/03/Screenshot-from-2022-03-29-22-47-30.png" alt="Backing up to the secondary cloud"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/03/Screenshot-from-2022-03-29-22-41-57.png" alt="Restoring files from cloud storage"></p><h3 id="归档个人数据" tabindex="-1">归档个人数据 <a class="header-anchor" href="#归档个人数据" aria-label="Permalink to “归档个人数据”">​</a></h3><p>不是所有数据都需要 3-2-1 备份策略。这就是个人数据共享。我将一台拥有 1TB 硬盘的笔记本作为我个人数据的档案（家庭照片）。</p><p>转到设置中的 “<ruby>共享<rt>Sharing</rt></ruby>” （在我的例子中是 GNOME 文件管理器）并切换滑块以启用共享。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-14-20-48-49-1024x733.png" alt=""></p><p>打开 “<ruby>文件共享<rt>file sharing</rt></ruby>”，“<ruby>网络<rt>Networks</rt></ruby>” 和 “<ruby>需要的密码<rt>Required password</rt></ruby>”，允许你使用 WebDAV 协议在你的本地网络上分享你的公共文件夹给其它的工作站。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-14-20-51-18st.png" alt=""></p><h3 id="准备回滚选项" tabindex="-1">准备回滚选项 <a class="header-anchor" href="#准备回滚选项" aria-label="Permalink to “准备回滚选项”">​</a></h3><p>未测试的备份并不比完全没有备份好。我在家庭实验室环境中使用 “热切换” 方法来避免像频繁的断电或者液体损坏的情况发生。然而，我的建议方案远没有达到灾难恢复计划或企业 IT 中的自动故障修复。</p><ul><li>定期运行文件恢复操作</li><li>备份 ssh/GPG 密钥到一个额外的存储设备中</li><li>复制一个 Fedora ARM 服务器的原始镜像到一个 SD 卡中</li><li>在主云存储中保持全备份的快照</li><li>自动化备份过程最小化减少人为错误或者疏忽</li></ul><h3 id="使用-cockpit-追踪活动并解决问题" tabindex="-1">使用 Cockpit 追踪活动并解决问题 <a class="header-anchor" href="#使用-cockpit-追踪活动并解决问题" aria-label="Permalink to “使用 Cockpit 追踪活动并解决问题”">​</a></h3><p>当你的项目在成长时，你所管理的服务器数量也在增长。在 Cockpit 中追踪活动和警告可以减轻你的管理负担。你可以使用 Cockpit 的图形化界面的三种方法来归档这些。</p><h4 id="selinux-菜单" tabindex="-1">SELinux 菜单 <a class="header-anchor" href="#selinux-菜单" aria-label="Permalink to “SELinux 菜单”">​</a></h4><p>怎样诊断网络问题，找到日志并在 Cockpit 中解决问题：</p><ul><li>去 SELinux 中检查日志</li><li>检查“<ruby>解决方案详细信息<rt>solution details</rt></ruby>”</li><li>当必要时，选择 “<ruby>应用这个方案<rt>Apply this solution</rt></ruby>”</li><li>如果必要，查看自动化脚本并运行它</li></ul><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-02-11-24-30b-1024x441.png" alt="SELinux logs"></p><h4 id="网络或者存储日志" tabindex="-1">网络或者存储日志 <a class="header-anchor" href="#网络或者存储日志" aria-label="Permalink to “网络或者存储日志”">​</a></h4><p>服务器日志会跟踪 CPU 负载、内存使用、网络活动、存储性能和系统日志关联的详细指标。日志会组织在网络面板或者存储面板里显示。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-04-21-47-06SL-1024x259.png" alt="Storage logs in Cockpit"></p><h4 id="软件更新" tabindex="-1">软件更新 <a class="header-anchor" href="#软件更新" aria-label="Permalink to “软件更新”">​</a></h4><p>在预设的时间和频率下，Cockpit 可以帮助进行安全更新。当你需要时，你可以运行所有的更新。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/04/Screenshot-from-2022-04-04-21-35-42b.png" alt="Software updates"></p><p>恭喜你在 Fedora ARM 服务器版本上搭建了一个文件/备份服务器。</p><hr>',25)),r("p",null,[e[29]||(e[29]=a("via: ",-1)),t(i,{href:"https://fedoramagazine.org/3-2-1-backup-plan-with-fedora-arm-server/"},{default:s(()=>[...e[28]||(e[28]=[a("https://fedoramagazine.org/3-2-1-backup-plan-with-fedora-arm-server/",-1)])]),_:1})]),r("p",null,[e[34]||(e[34]=a("作者：",-1)),t(i,{href:"https://fedoramagazine.org/author/hankuoffroad/"},{default:s(()=>[...e[30]||(e[30]=[a("Hanku Lee",-1)])]),_:1}),e[35]||(e[35]=a(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[31]||(e[31]=[a("lujun9972",-1)])]),_:1}),e[36]||(e[36]=a(" 译者：",-1)),t(i,{href:"https://github.com/hwlife"},{default:s(()=>[...e[32]||(e[32]=[a("hwlife",-1)])]),_:1}),e[37]||(e[37]=a(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:s(()=>[...e[33]||(e[33]=[a("wxy",-1)])]),_:1})]),r("p",null,[e[40]||(e[40]=a("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[38]||(e[38]=[a("LCTT",-1)])]),_:1}),e[41]||(e[41]=a(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:s(()=>[...e[39]||(e[39]=[a("Linux中国",-1)])]),_:1}),e[42]||(e[42]=a(" 荣誉推出",-1))])])}const C=o(h,[["render",u]]);export{S as __pageData,C as default};
